import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import sharp from 'sharp';
import {writeVerifiedBinary,writeGeneratedText,encodeGeneratedAssetOutputs} from './generated-asset-output.mjs';
const root=process.cwd(),out=path.resolve(root,'../heart-lab-work/assets');fs.mkdirSync(out,{recursive:true});const registry=[],map={},writtenDigests=new Map();
// A5-265: a full digest and MIME type identify the same generated bytes once per build.
function add(id,data,type,sha){const key=type+':'+sha;if(writtenDigests.has(key))return '/api/study-assets/'+writtenDigests.get(key);writeVerifiedBinary(path.join(out,id),data);writtenDigests.set(key,id);registry.push({id,sha,size:data.length,type});return '/api/study-assets/'+id}
// A5-264: at most three memory-bounded sharp jobs run concurrently; emit in input order.
async function orderedBatches(rows,width,transform,emit){for(let at=0;at<rows.length;at+=width){const batch=await Promise.all(rows.slice(at,at+width).map(transform));for(const value of batch)if(value)emit(value)}}
const model=fs.readFileSync('.sites-runtime/heart-lab/heart.glb');const modelSha=createHash('sha256').update(model).digest('hex');if(modelSha!=='b80a727d022a4ab07ccfcf15caccc228eaccb6d69ec0e72923324946ac35a946')throw Error('Wrong model');add('heart-v1',model,'model/gltf-binary',modelSha);
const walk=d=>fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(d,e.name)):[path.join(d,e.name)]);
const files=['materials','study_material','cvp-week3-figures','cvp-pulmonary-figures','mol-metabolism-figures'].filter(d=>fs.existsSync('public/'+d)).flatMap(d=>walk('public/'+d)).filter(p=>/\.(webp|png|jpe?g)$/i.test(p));
await orderedBatches(files,3,async file=>{try{const original=fs.readFileSync(file);if(original.length<30000)return null;const meta=await sharp(original).metadata();if(!meta.width||meta.width<=600||meta.pages>1)return null;const entry={width:meta.width,height:meta.height},key=file.replace(/^public\//,''),assets=[];for(const width of [480,960]){if(meta.width<=width)continue;const bytes=await sharp(original).rotate().resize({width,withoutEnlargement:true}).webp({quality:78}).toBuffer();if(bytes.length>=original.length*.9)continue;const sha=createHash('sha256').update(bytes).digest('hex');assets.push({id:'diagram-'+sha.slice(0,20)+'-'+width,width,bytes,sha})}return {file,key,entry,assets}}catch(e){console.warn('Skipped unreadable image',file);return null}},({file,key,entry,assets})=>{try{for(const {id,width,bytes,sha} of assets)entry[width]=add(id,bytes,'image/webp',sha);if(entry[480]||entry[960])map[(key.startsWith('materials/')||key.startsWith('study_material/')?'/api/site-assets/':'/')+key]=entry}catch(e){console.warn('Skipped unreadable image',file)}});
for(const [file,text] of encodeGeneratedAssetOutputs(registry,map))writeGeneratedText(file,text);console.log({files:registry.length,diagrams:Object.keys(map).length,bytes:registry.reduce((n,r)=>n+r.size,0)});
